'use strict';
/* InNav Environment Editor — client-side, dependency-free prototype.
 * All coordinates use an editable 1000 × 650 plan coordinate system.
 * Projects persist only in this browser's localStorage; exported JSON is portable.
 */
const STORE='innav-editor-projects-v1';
const $=(s,root=document)=>root.querySelector(s);
const $$=(s,root=document)=>[...root.querySelectorAll(s)];
const uid=(p='id')=>`${p}_${Math.random().toString(36).slice(2,10)}`;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
const deep=o=>JSON.parse(JSON.stringify(o));
const stamp=()=>new Date().toISOString();
const catList=['Entrance','Reception','Office','Classroom','Meeting room','Laboratory','Toilet','Lift','Staircase','Cafeteria','Emergency exit','Custom'];
const roomTypes=['Room','Hallway','Office','Classroom','Laboratory','Meeting room','Toilet','Lobby','Stairs','Lift','Utility'];
const nodeTypes=['hallway','junction','lift','stairs','entrance'];
let projects=[],currentId=null,view='dashboard',floorId=null,selection=null,tool='select',route=null,dirty=false,history=[],future=[],routeFrom='',routeTo='',viewMode='2d',showGrid=true,showGraph=true,showPOI=true,searchTerm='',listFilter='',zoom=1,pan={x:0,y:0},drag=null,edgeStart=null;
const project=()=>projects.find(p=>p.id===currentId)||null;
const floor=()=>project()?.floors.find(f=>f.id===floorId)||project()?.floors[0]||null;
let selected=()=>{let p=project();if(!p||!selection)return null;let {type,id}=selection;return type==='building'?p:type==='floor'?p.floors.find(x=>x.id===id):p[type==='room'?'rooms':type==='poi'?'pois':type==='node'?'nodes':'edges']?.find(x=>x.id===id)};
const fName=id=>project()?.floors.find(f=>f.id===id)?.name||'Unknown floor';
const fNum=id=>project()?.floors.find(f=>f.id===id)?.number??'?';
const count=(p,key)=>p[key]?.length||0;
